{
  "dashboard": {
    "title": "Kubernetes Resource Utilization (v1.33+)",
    "panels": [
      {
        "title": "Node CPU Usage",
        "targets": [
          {
            "expr": "rate(node_cpu_usage_seconds_total[5m])",
            "legendFormat": "{{node}}"
          }
        ]
      },
      {
        "title": "Pod Memory Working Set",
        "targets": [
          {
            "expr": "pod_memory_working_set_bytes",
            "legendFormat": "{{pod}}"
          }
        ]
      }
    ]
  }
}
